#include <list>
#include <algorithm>

int main() {
    std::list<int> L = {1, 2, 3};

    // Guaranteed not to throw
    L.pop_back();
    L.erase(L.begin());

    std::list<int> L2 = {10, 20};
    L.swap(L2); // O(1) and guaranteed not to throw

    // Conditional non-throw guarantee:
    // If custom_predicate throws, behavior is indeterminate.
    // L.remove_if(custom_predicate);

    L.clear(); // Guaranteed not to throw
}
